", "src/App.jsx": "import { Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import Footer from './components/Footer';
import Home from './screens/Home';
import FitnessTracker from './screens/FitnessTracker';
import MealPlanner from './screens/MealPlanner';
import MentalWellness from './screens/MentalWellness';
import SleepMonitor from './screens/SleepMonitor';
import Reports from './screens/Reports';
import CommunityForum from './screens/CommunityForum';
import Profile from './screens/Profile';

function App() {
  return (
    <div className="flex min-h-screen bg-gray-100 font-sans">
      <Sidebar />
      <div className="flex-1 flex flex-col">
        <Navbar />
        <main className="flex-1 p-6">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/fitness" element={<FitnessTracker />} />
            <Route path="/meal-planner" element={<MealPlanner />} />
            <Route path="/mental-wellness" element={<MentalWellness />} />
            <Route path="/sleep-monitor" element={<SleepMonitor />} />
            <Route path="/reports" element={<Reports />} />
            <Route path="/community" element={<CommunityForum />} />
            <Route path="/profile" element={<Profile />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </div>
  );
}

export default App;
