", "src/screens/FitnessTracker.jsx": "import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { addFitnessGoal } from '../slices/userDataSlice';
import { v4 as uuidv4 } from 'uuid';

function FitnessTracker() {
  const dispatch = useDispatch();
  const fitnessGoals = useSelector((state) => state.user.progress.fitnessGoals);
  const workoutRecommendations = useSelector((state) => state.recommendations.workoutPlans);
  const [newGoal, setNewGoal] = useState('');

  const handleAddGoal = () => {
    if (newGoal.trim()) {
      dispatch(addFitnessGoal({ id: uuidv4(), name: newGoal, completed: false }));
      setNewGoal('');
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Fitness Tracker</h1>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Your Fitness Goals</h2>
          <div className="flex mb-4">
            <input
              type="text"
              className="flex-1 border border-gray-300 rounded-l-md p-2 focus:ring-blue-500 focus:border-blue-500"
              placeholder="Add a new fitness goal"
              value={newGoal}
              onChange={(e) => setNewGoal(e.target.value)}
            />
            <button
              onClick={handleAddGoal}
              className="bg-blue-600 text-white px-4 py-2 rounded-r-md hover:bg-blue-700 transition-colors"
            >
              Add Goal
            </button>
          </div>
          {fitnessGoals.length > 0 ? (
            <ul className="space-y-2">
              {fitnessGoals.map((goal) => (
                <li key={goal.id} className="flex items-center bg-gray-50 p-3 rounded-md">
                  <input
                    type="checkbox"
                    checked={goal.completed}
                    className="mr-2 h-4 w-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                    readOnly
                  />
                  <span className={`${goal.completed ? 'line-through text-gray-500' : 'text-gray-800'}`}>
                    {goal.name}
                  </span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-600">No fitness goals set yet. Start by adding one!</p>
          )}
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">AI Workout Recommendations</h2>
          {workoutRecommendations.length > 0 ? (
            <ul className="list-disc list-inside space-y-2 text-gray-700">
              {workoutRecommendations.map((rec) => (
                <li key={rec.id || uuidv4()}>
                  <span className="font-semibold">{rec.name}:</span> {rec.description}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-600">No personalized workout recommendations yet. Keep tracking your activity!</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default FitnessTracker;
