", "src/screens/MentalWellness.jsx": "import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { setMeditations, startMeditationSession, endMeditationSession } from '../slices/meditationSuggestionsSlice';
import { setStressManagementTips } from '../slices/recommendationSlice'; // Import setStressManagementTips
import { v4 as uuidv4 } from 'uuid';

function MentalWellness() {
  const dispatch = useDispatch();
  const meditations = useSelector((state) => state.meditation.meditations);
  const currentSession = useSelector((state) => state.meditation.currentSession);
  const stressTips = useSelector((state) => state.recommendations.stressManagementTips);

  // Simulate loading meditations and stress tips on component mount
  React.useEffect(() => {
    if (meditations.length === 0) {
      dispatch(setMeditations([
        { id: uuidv4(), name: '5-Minute Mindful Breathing', description: 'Focus on your breath to calm your mind.' },
        { id: uuidv4(), name: '10-Minute Body Scan', description: 'Tune into physical sensations for relaxation.' },
        { id: uuidv4(), name: 'Guided Sleep Meditation', description: 'Prepare for restful sleep with gentle guidance.' },
      ]));
    }
    if (stressTips.length === 0) {
       dispatch(setStressManagementTips([
        { id: uuidv4(), tip: 'Practice deep breathing exercises daily.' },
        { id: uuidv4(), tip: 'Take short breaks throughout your workday.' },
        { id: uuidv4(), tip: 'Ensure you get enough sleep each night.' },
      ]));
    }
  }, [dispatch, meditations.length, stressTips.length]);

  const handleStartSession = (meditationId) => {
    dispatch(startMeditationSession({ id: meditationId, duration: 0 }));
  };

  const handleEndSession = () => {
    dispatch(endMeditationSession());
  };

  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Mental Wellness</h1>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Meditation Suggestions</h2>
          {meditations.length > 0 ? (
            <ul className="space-y-4">
              {meditations.map((meditation) => (
                <li key={meditation.id} className="p-4 bg-gray-50 rounded-md shadow-sm">
                  <h3 className="text-lg font-semibold text-gray-900">{meditation.name}</h3>
                  <p className="text-gray-700 mb-2">{meditation.description}</p>
                  {currentSession && currentSession.id === meditation.id ? (
                    <button
                      onClick={handleEndSession}
                      className="bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-600 transition-colors"
                    >
                      End Session
                    </button>
                  ) : (
                    <button
                      onClick={() => handleStartSession(meditation.id)}
                      className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 transition-colors"
                      disabled={!!currentSession}
                    >
                      {currentSession ? 'Session Active' : 'Start Session'}
                    </button>
                  )}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-600">No meditation suggestions available. Check back later!</p>
          )}
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-semibold text-gray-800 mb-4">Stress Management Tips</h2>
          {stressTips.length > 0 ? (
            <ul className="list-disc list-inside space-y-2 text-gray-700">
              {stressTips.map((tip) => (
                <li key={tip.id || uuidv4()}>{tip.tip}</li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-600">No stress management tips available yet.</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default MentalWellness;
