const initialState = {
  meditations: [],
  currentSession: null,
  history: [],
};

const meditationSuggestionsSlice = createSlice({
  name: 'meditation',
  initialState,
  reducers: {
    setMeditations: (state, action) => {
      state.meditations = action.payload;
    },
    startMeditationSession: (state, action) => {
      state.currentSession = { id: action.payload.id, startTime: Date.now(), duration: action.payload.duration || 0 };
    },
    endMeditationSession: (state) => {
      if (state.currentSession) {
        state.history.push({ ...state.currentSession, endTime: Date.now() });
        state.currentSession = null;
      }
    },
  },
});

export const { setMeditations, startMeditationSession, endMeditationSession } = meditationSuggestionsSlice.actions;
export default meditationSuggestionsSlice.reducer;
", "src/slices/challengeSlice.js": "import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  activeChallenges: [],
  completedChallenges: [],
  availableChallenges: [],
};

const challengeSlice = createSlice({
  name: 'challenges',
  initialState,
  reducers: {
    setAvailableChallenges: (state, action) => {
      state.availableChallenges = action.payload;
    },
    startChallenge: (state, action) => {
      state.activeChallenges.push(action.payload);
      state.availableChallenges = state.availableChallenges.filter(
        (c) => c.id !== action.payload.id
      );
    },
    completeChallenge: (state, action) => {
      state.activeChallenges = state.activeChallenges.filter(
        (c) => c.id !== action.payload.id
      );
      state.completedChallenges.push(action.payload);
    },
  },
});

export const { setAvailableChallenges, startChallenge, completeChallenge } = challengeSlice.actions;
export default challengeSlice.reducer;
