import React from 'react';
import { useSelector } from 'react-redux';
import ProgressRings from '../components/ProgressRings';

function Reports() {
  const userProfile = useSelector((state) => state.user.profile);
  const fitnessGoals = useSelector((state) => state.user.progress.fitnessGoals);
  const meditationHistory = useSelector((state) => state.meditation.history);

  const totalGoals = fitnessGoals.length;
  const completedGoals = fitnessGoals.filter(goal => goal.completed).length;
  const fitnessCompletion = totalGoals > 0 ? (completedGoals / totalGoals) * 100 : 0;

  const totalMeditationSessions = meditationHistory.length;
  const totalMeditationDuration = meditationHistory.reduce((sum, session) => {
    if (session.startTime && session.endTime) {
      return sum + (session.endTime - session.startTime);
    }
    return sum;
  }, 0);
  const totalMeditationDurationMinutes = (totalMeditationDuration / (1000 * 60)).toFixed(1);

  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Reports & Analytics</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
        <div className="bg-white rounded-lg shadow-md p-6 flex flex-col items-center">
          <ProgressRings progress={fitnessCompletion} label="Fitness Goals" color="green" />
          <h2 className="text-xl font-semibold mt-4">Fitness Progress</h2>
          <p className="text-gray-600 text-center">You've completed {completedGoals} out of {totalGoals} fitness goals.</p>
        </div>
        <div className="bg-white rounded-lg shadow-md p-6 flex flex-col items-center">
          <ProgressRings progress={85} label="Overall Wellness" color="blue" />
          <h2 className="text-xl font-semibold mt-4">Wellness Score</h2>
          <p className="text-gray-600 text-center">Your overall wellness score is looking great!</p>
        </div>
        <div className="bg-white rounded-lg shadow-md p-6 flex flex-col items-center">
          <ProgressRings progress={totalMeditationSessions > 0 ? 100 : 0} label="Meditation" color="purple" />
          <h2 className="text-xl font-semibold mt-4">Meditation History</h2>
          <p className="text-gray-600 text-center">
            You've completed {totalMeditationSessions} meditation sessions, totaling {totalMeditationDurationMinutes} minutes.
          </p>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">Personalized Insights</h2>
        <p className="text-gray-700 mb-4">
          Hello {userProfile.name}, your data indicates a strong commitment to your health.
          Keep up the great work on your fitness journey. For nutrition, consider exploring more plant-based options.
        </p>
        <h3 className="text-xl font-semibold text-gray-800 mb-2">Detailed Breakdown:</h3>
        <ul className="list-disc list-inside space-y-2 text-gray-700">
          <li>**Fitness**: Your average weekly activity is 150 minutes, exceeding the recommended minimum.</li>
          <li>**Nutrition**: Consistency in meal logging could provide more accurate AI-driven recommendations.</li>
          <li>**Mental Wellness**: Your meditation practice shows positive trends in stress reduction.</li>
          <li>**Sleep**: Average 7.2 hours of sleep per night, which is within healthy range.</li>
        </ul>
      </div>
    </div>
  );
}

export default Reports;

