import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { updateUserProfile } from '../slices/userDataSlice';
import Avatar from '../components/Avatar';

function Profile() {
  const dispatch = useDispatch();
  const userProfile = useSelector((state) => state.user.profile);

  const [editMode, setEditMode] = useState(false);
  const [formData, setFormData] = useState({
    name: userProfile.name,
    age: userProfile.age,
    weight: userProfile.weight,
    height: userProfile.height,
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSave = () => {
    dispatch(updateUserProfile(formData));
    setEditMode(false);
  };

  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">User Profile</h1>

      <div className="bg-white rounded-lg shadow-md p-6 max-w-2xl mx-auto">
        <div className="flex flex-col items-center mb-6">
          <Avatar imageUrl="https://via.placeholder.com/150" size="large" />
          <h2 className="text-2xl font-semibold text-gray-800 mt-4">{userProfile.name}</h2>
          <p className="text-gray-600">Health Enthusiast</p>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Name</label>
            {editMode ? (
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-blue-500 focus:border-blue-500"
              />
            ) : (
              <p className="mt-1 text-lg text-gray-900">{userProfile.name}</p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Age</label>
            {editMode ? (
              <input
                type="number"
                name="age"
                value={formData.age}
                onChange={handleChange}
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-blue-500 focus:border-blue-500"
              />
            ) : (
              <p className="mt-1 text-lg text-gray-900">{userProfile.age} years</p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Weight (kg)</label>
            {editMode ? (
              <input
                type="number"
                name="weight"
                value={formData.weight}
                onChange={handleChange}
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-blue-500 focus:border-blue-500"
              />
            ) : (
              <p className="mt-1 text-lg text-gray-900">{userProfile.weight} kg</p>
            )}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Height (cm)</label>
            {editMode ? (
              <input
                type="number"
                name="height"
                value={formData.height}
                onChange={handleChange}
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2 focus:ring-blue-500 focus:border-blue-500"
              />
            ) : (
              <p className="mt-1 text-lg text-gray-900">{userProfile.height} cm</p>
            )}
          </div>
        </div>

        <div className="mt-6 flex justify-end space-x-3">
          {editMode ? (
            <>
              <button
                onClick={() => {
                  setEditMode(false);
                  setFormData(userProfile);
                }}
                className="px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                Cancel
              </button>
              <button
                onClick={handleSave}
                className="px-4 py-2 bg-blue-600 border border-transparent rounded-md shadow-sm text-sm font-medium text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                Save Changes
              </button>
            </>
          ) : (
            <button
              onClick={() => setEditMode(true)}
              className="px-4 py-2 bg-blue-600 border border-transparent rounded-md shadow-sm text-sm font-medium text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
            >
              Edit Profile
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export default Profile;

