import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';

function Notifications() {
  const [notifications, setNotifications] = useState([
    { id: uuidv4(), message: 'Your personalized workout plan is ready!', read: false },
    { id: uuidv4(), message: 'You completed the daily step challenge!', read: true },
    { id: uuidv4(), message: 'New meditation session available.', read: false },
  ]);
  const [isOpen, setIsOpen] = useState(false);

  const unreadCount = notifications.filter(n => !n.read).length;

  const toggleOpen = () => setIsOpen(!isOpen);

  const markAsRead = (id) => {
    setNotifications(notifications.map(n =>
      n.id === id ? { ...n, read: true } : n
    ));
  };

  return (
    <div className="relative">
      <button
        onClick={toggleOpen}
        className="relative p-2 rounded-full bg-gray-200 hover:bg-gray-300 transition-colors"
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="h-6 w-6 text-gray-600"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="2"
            d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"
          />
        </svg>
        {unreadCount > 0 && (
          <span className="absolute top-0 right-0 inline-flex items-center justify-center px-2 py-1 text-xs font-bold leading-none text-red-100 bg-red-600 rounded-full">
            {unreadCount}
          </span>
        )}
      </button>

      {isOpen && (
        <div className="absolute right-0 mt-2 w-72 bg-white rounded-md shadow-lg py-1 z-20 max-h-80 overflow-y-auto">
          <div className="px-4 py-2 text-sm font-semibold text-gray-700 border-b">Notifications</div>
          {notifications.length === 0 ? (
            <div className="px-4 py-3 text-sm text-gray-500">No new notifications.</div>
          ) : (
            notifications.map((notification) => (
              <div
                key={notification.id}
                className={`flex items-center justify-between px-4 py-3 hover:bg-gray-50 transition-colors ${
                  !notification.read ? 'bg-blue-50' : ''
                }`}
              >
                <p className={`text-sm ${notification.read ? 'text-gray-600' : 'font-medium text-gray-800'}`}>
                  {notification.message}
                </p>
                {!notification.read && (
                  <button
                    onClick={() => markAsRead(notification.id)}
                    className="ml-2 px-2 py-1 text-xs text-blue-600 hover:text-blue-800 rounded-md bg-blue-100 hover:bg-blue-200 transition-colors"
                  >
                    Mark as Read
                  </button>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

export default Notifications;

