import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  profile: {
    name: 'John Doe',
    age: 30,
    weight: 75,
    height: 175,
  },
  progress: {
    fitnessGoals: [],
    nutritionGoals: [],
  },
};

const userDataSlice = createSlice({
  name: 'user',
  initialState,
  reducers: {
    updateUserProfile: (state, action) => {
      state.profile = { ...state.profile, ...action.payload };
    },
    addFitnessGoal: (state, action) => {
      state.progress.fitnessGoals.push(action.payload);
    },
    addNutritionGoal: (state, action) => {
      state.progress.nutritionGoals.push(action.payload);
    },
  },
});

export const { updateUserProfile, addFitnessGoal, addNutritionGoal } = userDataSlice.actions;
export default userDataSlice.reducer;

