import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  meditations: [],
  currentSession: null,
  history: [],
};

const meditationSuggestionsSlice = createSlice({
  name: 'meditation',
  initialState,
  reducers: {
    setMeditations: (state, action) => {
      state.meditations = action.payload;
    },
    startMeditationSession: (state, action) => {
      state.currentSession = { id: action.payload.id, startTime: Date.now(), duration: action.payload.duration || 0 };
    },
    endMeditationSession: (state) => {
      if (state.currentSession) {
        state.history.push({ ...state.currentSession, endTime: Date.now() });
        state.currentSession = null;
      }
    },
  },
});

export const { setMeditations, startMeditationSession, endMeditationSession } = meditationSuggestionsSlice.actions;
export default meditationSuggestionsSlice.reducer;

