import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  activeChallenges: [],
  completedChallenges: [],
  availableChallenges: [],
};

const challengeSlice = createSlice({
  name: 'challenges',
  initialState,
  reducers: {
    setAvailableChallenges: (state, action) => {
      state.availableChallenges = action.payload;
    },
    startChallenge: (state, action) => {
      state.activeChallenges.push(action.payload);
      state.availableChallenges = state.availableChallenges.filter(
        (c) => c.id !== action.payload.id
      );
    },
    completeChallenge: (state, action) => {
      state.activeChallenges = state.activeChallenges.filter(
        (c) => c.id !== action.payload.id
      );
      state.completedChallenges.push(action.payload);
    },
  },
});

export const { setAvailableChallenges, startChallenge, completeChallenge } = challengeSlice.actions;
export default challengeSlice.reducer;
